setup.store/records.py:
"""Record access."""

_DB = {i: {"id": i, "name": f"record-{i}", "total": i * 10.0} for i in range(1, 200)}


def fetch_record(id, strict):
    """Return the record `id`; with `strict`, a missing record raises KeyError."""
    if id not in _DB:
        if strict:
            raise KeyError(id)
        return None
    return dict(_DB[id])

