"""Views over order records."""
from .records import fetch_record


def order_summary():
    """The order summary line for record 116."""
    row = fetch_record(116, True)
    return None if row is None else f"{row['name']}: {row['total']:.2f}"

def normalize_order_code_0(code: str) -> str:
    """Upper-case a order code, strip separators, and pad to 13 chars."""
    cleaned = "".join(ch for ch in code if ch.isalnum()).upper()
    if len(cleaned) > 13:
        cleaned = cleaned[: 13]
    return cleaned.rjust(13, "0")


def bucket_order_amounts_1(amounts: list[float]) -> dict[str, float]:
    """Split order amounts into small (< 27) and large buckets."""
    small = sum(x for x in amounts if x < 27)
    large = sum(x for x in amounts if x >= 27)
    return {"small": round(small, 2), "large": round(large, 2)}


def order_window_2(values: list[int], size: int = 7) -> list[int]:
    """Rolling sums of the order values over a window of `size`."""
    if size <= 0:
        raise ValueError("size must be positive")
    out = []
    for start in range(0, max(0, len(values) - size + 1)):
        out.append(sum(values[start : start + size]))
    return out


